mapper.select:
SELECT m.*, COUNT(p.participant_id) AS current_people, CASE WHEN f.match_id IS NOT NULL THEN 1 ELSE 0 END AS favorite FROM personal_match m LEFT JOIN personal_match_participant p ON m.personal_match_id = p.personal_match_id LEFT JOIN favorite f ON f.match_id = m.personal_match_id AND f.match_type = 'Personal' AND f.user_id = #{userId} WHERE coalesce(m.deleted, 0) = 0 AND m.status = '모집중'
AND m.personal_match_id NOT IN
#{id}
GROUP BY m.personal_match_id ORDER BY m.created_at DESC LIMIT #{limit}

SELECT m.*, COUNT(p.participant_id) AS current_people, CASE WHEN f.match_id IS NOT NULL THEN 1 ELSE 0 END AS favorite FROM personal_match m LEFT JOIN personal_match_participant p ON m.personal_match_id = p.personal_match_id LEFT JOIN favorite f ON f.match_id = m.personal_match_id AND f.match_type = 'Personal' AND f.user_id = #{userId} WHERE 1=1 AND coalesce(m.deleted, 0) = 0 AND m.status ='모집중'
AND m.sport IN
#{sport}
AND (
m.age_20s = true
m.age_30s = true
m.age_40s = true
m.age_50s = true
m.age_60_plus = true
)
AND (
m.skill_intro = true
m.skill_beginner = true
m.skill_intermediate = true
m.skill_advanced = true
)
AND m.gender = #{gender}
AND m.region IN
#{region}
AND m.match_date >= #{startDate}
AND m.match_date <= #{endDate}
AND ( m.title LIKE CONCAT('%', #{keyword}, '%') OR m.content LIKE CONCAT('%', #{keyword}, '%') )
GROUP BY m.personal_match_id ORDER BY m.created_at DESC LIMIT #{startIndex}, 4

SELECT m.*, m.min_people AS minPeople, m.max_people AS maxPeople, (SELECT COUNT(*) FROM personal_match_participant cp WHERE cp.personal_match_id = m.personal_match_id AND cp.status = '결제완료') AS currentPeople, p.status AS participantStatus, CASE WHEN f.favorite_id IS NULL THEN 0 ELSE 1 END AS favorite FROM personal_match_participant p JOIN personal_match m ON m.personal_match_id = p.personal_match_id LEFT JOIN favorite f ON f.match_id = m.personal_match_id AND f.user_id = #{userId} AND f.match_type = 'Personal' WHERE p.user_id = #{userId} AND p.status IN ('결제완료', '취소')
AND m.sport = #{sport}
AND m.status = #{status}
AND m.match_date >= #{startDate}
AND m.match_date <= #{endDate}
ORDER BY m.match_date DESC, m.personal_match_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM personal_match_participant p
JOIN personal_match m
ON m.personal_match_id = p.personal_match_id
WHERE p.user_id =
#{userId}
AND p.status IN ('결제완료', '취소')

	AND m.sport = #{sport}


	AND m.status = #{status}


	AND m.match_date >= #{startDate}


	AND m.match_date <= #{endDate}

		SELECT m.*,
		m.min_people AS minPeople,
       	m.max_people AS maxPeople,
       	 (SELECT COUNT(*)
          FROM personal_match_participant cp
         WHERE cp.personal_match_id = m.personal_match_id
           AND cp.status = '결제완료') AS currentPeople,
		CASE WHEN f.favorite_id IS NULL THEN 0 ELSE 1 END AS
		favorite
		FROM personal_match m
		LEFT JOIN favorite f
		ON f.match_id =
		m.personal_match_id
		AND f.user_id = #{userId}
		AND f.match_type
		='Personal'
		WHERE m.user_id = #{userId}
		AND m.deleted = '0'

			AND m.sport = #{sport}


			AND m.status = #{status}

		 AND m.match_date >= #{startDate} 
		 AND m.match_date <= #{endDate} 
		ORDER BY m.match_date DESC, m.personal_match_id DESC
		LIMIT #{size}
		OFFSET #{offset}

SELECT COUNT(*)
FROM personal_match m
WHERE m.user_id = #{userId}
AND
m.deleted = '0'

	AND m.sport = #{sport}


	AND m.status = #{status}

 AND m.match_date >= #{startDate} 
 AND m.match_date <= #{endDate}

