SELECT DISTINCT DATE_FORMAT(m.match_date, '%Y-%m-%d')
FROM
personal_match_participant p
JOIN personal_match m
ON
m.personal_match_id = p.personal_match_id
WHERE p.user_id = #{userId}
AND p.status IN ('결제완료', '취소')

	AND m.sport = #{sport}


	AND m.status = #{status}

SELECT DISTINCT DATE_FORMAT(m.match_date, '%Y-%m-%d')
FROM
personal_match m
WHERE m.user_id = #{userId}
AND m.deleted = '0'

	AND m.sport = #{sport}


	AND m.status = #{status}
